CREATE TEMPORARY VIEW dwd_search_${grass_region_without_quote} AS
SELECT
    user_id
    ,a.page_type
    ,a.target_type
    ,IF(is_ads IS NOT NULL, is_ads, false) AS is_ads
    ,location
    ,CASE 
        WHEN a.target_type = 'item'
            THEN item_id
        ELSE content_id
    END AS distinct_id
    ,global_session_id
    ,search_session_id
    ,search_entrance
    ,COALESCE(search_mid, '') AS search_mid
    ,trim(lower(keyword)) AS keyword
    ,event_timestamp
    ,CASE
        WHEN operation in ('click') AND target_type IN ('item', 'video', 'livestream')
            THEN row_number() over(partition by global_session_id, search_session_id, search_entrance ,COALESCE(search_mid, ''), keyword, user_id, operation, IF(target_type IN ('item', 'video', 'livestream'), true, false)
                    order by event_timestamp asc)
        ELSE NULL
    END AS time_rank
    ,CASE
        WHEN operation in ('view') 
            THEN row_number() over(partition by global_session_id, search_session_id, search_entrance ,COALESCE(search_mid, ''), keyword, user_id, operation
                    order by event_timestamp asc)
        ELSE NULL
    END AS view_time_rank
    ,IF(target_type IN ('item', 'video', 'livestream'), true, false) AS if_oa_card
    ,operation
    ,session_id
    ,request_id
    
    ,operation_cnt
    ,place_order_gmv
FROM
    srdi_mart.dwd_sr_data_warehouse_search a
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND operation IN ('impression', 'click', 'order', 'view')
    AND a.page_type IN ('global_search', 'search_in_pdp', 'search_prefill')       
    AND COALESCE(search_session_id, '') != ''
UNION ALL
