CREATE TEMPORARY VIEW dws_search_main_${grass_region_without_quote} AS
SELECT
    user_id
    ,search_session_id
    ,global_session_id
    ,MAX(IF(operation = 'view' AND view_time_rank = 1 , page_type, NULL)) AS page_type
    ,search_entrance
    ,search_mid
    ,keyword
    ,MAX(IF(operation = 'view' AND view_time_rank = 1 , session_id, NULL)) AS session_id

    ,SUM(IF(operation = 'impression' AND is_ads = false AND target_type = 'item', operation_cnt, NULL)) AS item_imp_cnt_org
    ,SUM(IF(operation = 'impression' AND is_ads = true AND target_type = 'item', operation_cnt, NULL)) AS item_imp_cnt_ads
    ,COUNT(DISTINCT IF(operation = 'impression' AND target_type = 'item', distinct_id, NULL)) as distinct_item_imp_cnt
    ,SUM(IF(operation = 'click' AND is_ads = false AND target_type = 'item', operation_cnt, NULL)) AS item_click_cnt_org
    ,SUM(IF(operation = 'click' AND is_ads = true AND target_type = 'item', operation_cnt, NULL)) AS item_click_cnt_ads
    ,COUNT(DISTINCT IF(operation = 'click' AND target_type = 'item', distinct_id, NULL)) as distinct_item_click_cnt
    ,SUM(IF(operation = 'order' AND is_ads = false AND target_type = 'item', operation_cnt, NULL)) AS item_order_cnt_org
    ,SUM(IF(operation = 'order' AND is_ads = true AND target_type = 'item', operation_cnt, NULL)) AS item_order_cnt_ads
    ,SUM(IF(operation = 'order' AND is_ads = false AND target_type = 'item', place_order_gmv, NULL)) AS item_gmv_org
    ,SUM(IF(operation = 'order' AND is_ads = true AND target_type = 'item', place_order_gmv, NULL)) AS item_gmv_ads
    ,COUNT(DISTINCT IF(operation = 'order' AND target_type = 'item', distinct_id, NULL)) as distinct_item_order_cnt

    ,SUM(IF(operation = 'impression' AND target_type = 'video', operation_cnt, NULL)) AS video_imp_cnt
    ,COUNT(DISTINCT IF(operation = 'impression' AND target_type = 'video', distinct_id, NULL)) as distinct_video_imp_cnt
    ,SUM(IF(operation = 'click' AND target_type = 'video', operation_cnt, NULL)) AS video_click_cnt
    ,COUNT(DISTINCT IF(operation = 'click' AND target_type = 'video', distinct_id, NULL)) as distinct_video_click_cnt
    ,SUM(IF(operation = 'order' AND target_type = 'video', operation_cnt, NULL)) AS video_order_cnt
    ,SUM(IF(operation = 'order' AND target_type = 'video', place_order_gmv, NULL)) AS video_gmv
    ,COUNT(DISTINCT IF(operation = 'order' AND target_type = 'video', distinct_id, NULL)) as distinct_video_order_cnt

    ,SUM(IF(operation = 'impression' AND target_type = 'livestream', operation_cnt, NULL)) AS live_imp_cnt
    ,COUNT(DISTINCT IF(operation = 'impression' AND target_type = 'livestream', distinct_id, NULL)) as distinct_live_imp_cnt
    ,SUM(IF(operation = 'click' AND target_type = 'livestream', operation_cnt, NULL)) AS live_click_cnt
    ,COUNT(DISTINCT IF(operation = 'click' AND target_type = 'livestream', distinct_id, NULL)) as distinct_live_click_cnt
    ,SUM(IF(operation = 'order' AND target_type = 'livestream', operation_cnt, NULL)) AS live_order_cnt
    ,SUM(IF(operation = 'order' AND target_type = 'livestream', place_order_gmv, NULL)) AS live_gmv
    ,COUNT(DISTINCT IF(operation = 'order' AND target_type = 'livestream', distinct_id, NULL)) as distinct_live_order_cnt

    ,SUM(IF(operation = 'impression' AND target_type IN ('item', 'video', 'livestream'), operation_cnt, NULL)) AS imp_cnt
    ,COUNT(DISTINCT IF(operation = 'impression' AND target_type IN ('item', 'video', 'livestream'), distinct_id, NULL)) as distinct_imp_cnt
    ,SUM(IF(operation = 'click' AND target_type IN ('item', 'video', 'livestream'), operation_cnt, NULL)) AS click_cnt
    ,COUNT(DISTINCT IF(operation = 'click' AND target_type IN ('item', 'video', 'livestream'), distinct_id, NULL)) as distinct_click_cnt
    ,SUM(IF(operation = 'order' AND target_type IN ('item', 'video', 'livestream'), operation_cnt, NULL)) AS order_cnt
    ,SUM(IF(operation = 'order' AND target_type IN ('item', 'video', 'livestream'), place_order_gmv, NULL)) AS gmv
    ,COUNT(DISTINCT IF(operation = 'order' AND target_type IN ('item', 'video', 'livestream'), distinct_id, NULL)) as distinct_order_cnt



    ,MAX(IF(operation = 'impression' AND target_type IN ('item', 'video', 'livestream'), location, NULL)) AS max_imp_location
    ,COUNT(DISTINCT IF(operation = 'impression' AND target_type IN ('item', 'video', 'livestream'), request_id, NULL)) as imp_request_cnt
    ,SUM(IF(operation = 'click' AND location = 0 AND target_type IN ('item', 'video', 'livestream'), operation_cnt, NULL)) AS click_top1
    ,SUM(IF(operation = 'click' AND location < 4 AND target_type IN ('item', 'video', 'livestream'), operation_cnt, NULL)) AS click_top4
    ,SUM(IF(operation = 'click' AND location < 20 AND target_type IN ('item', 'video', 'livestream'), operation_cnt, NULL)) AS click_top20
    ,MAX(IF(operation = 'click' AND time_rank = 1 AND if_oa_card = true, location, NULL)) AS first_click_location
    ,MAX(IF(operation = 'click' AND time_rank = 1 AND if_oa_card = true, target_type, NULL)) AS first_click_type
    ,AVG(DISTINCT(IF(operation = 'order' AND operation_cnt > 0 AND target_type IN ('item', 'video', 'livestream'), location, NULL)) ) AS avg_order_location

    ,MIN(IF(operation = 'view', event_timestamp, NULL )) AS search_time
    ,MAX(IF(operation = 'view', true, false)) AS is_view
FROM
    dwd_search_${grass_region_without_quote}
GROUP BY 
    user_id, search_session_id, global_session_id, search_entrance, search_mid, keyword;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_search_other_${grass_region_without_quote} AS
SELECT
    user_id
    ,search_session_id
    ,global_session_id
    ,keyword


    ,MAX(IF(target_type = 'shop' AND operation = 'impression', true, false)) AS is_shop_imp
    ,MAX(IF(target_type = 'no_recall_general' AND operation = 'impression', true, false)) AS is_no_recall
FROM
    dwd_search_${grass_region_without_quote}
WHERE
    operation = 'impression'
GROUP BY 
    user_id, search_session_id, global_session_id, keyword;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dim_user_${grass_region_without_quote} AS 
SELECT
    user_id
    ,FIRST(CASE gender
        WHEN 1 THEN 'Male'
        WHEN 2 THEN 'Female'
        WHEN 3 THEN 'Male'
        WHEN 4 THEN 'Female'
        ELSE 'Unknown'
    END) AS gender
    ,FIRST(age) AS age

FROM
    srdi_mart.dim_sr_data_warehouse_user
WHERE local_date = ${local_date}
AND grass_region = ${grass_region}
AND user_id > 0
GROUP BY 1;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_session_level_metircs_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
    a.user_id AS user_id
    ,age
    ,gender
    ,a.search_session_id
    ,a.global_session_id
    ,a.page_type
    ,a.search_entrance
    ,a.search_mid
    ,search_time
    ,a.keyword
    ,a.session_id


    ,item_imp_cnt_org
    ,item_imp_cnt_ads
    ,distinct_item_imp_cnt
    ,item_click_cnt_org
    ,item_click_cnt_ads
    ,distinct_item_click_cnt
    ,item_order_cnt_org
    ,item_order_cnt_ads
    ,item_gmv_org
    ,item_gmv_ads
    ,distinct_item_order_cnt

    ,live_imp_cnt
    ,distinct_live_imp_cnt
    ,live_click_cnt
    ,distinct_live_click_cnt
    ,live_order_cnt
    ,live_gmv
    ,distinct_live_order_cnt

    ,video_imp_cnt
    ,distinct_video_imp_cnt
    ,video_click_cnt
    ,distinct_video_click_cnt
    ,video_order_cnt
    ,video_gmv
    ,distinct_video_order_cnt

    ,max_imp_location
    ,imp_request_cnt
    ,click_top1
    ,click_top4
    ,click_top20
    ,first_click_location
    ,first_click_type
    ,avg_order_location
    ,is_shop_imp
    ,is_no_recall

    ,imp_cnt
    ,distinct_imp_cnt
    ,click_cnt
    ,distinct_click_cnt
    ,order_cnt
    ,gmv
    ,distinct_order_cnt
FROM 
    dws_search_main_${grass_region_without_quote} a
    LEFT JOIN dim_user_${grass_region_without_quote} b 
        ON a.user_id = b.user_id
    LEFT JOIN dws_search_other_${grass_region_without_quote} c
        ON a.user_id <=> c.user_id
        AND a.search_session_id = c.search_session_id
        AND a.global_session_id <=> c.global_session_id
        AND a.keyword <=> c.keyword
WHERE
    is_view = true;
